import 'package:flutter/material.dart';
import '../../../services/business_configuration_service.dart';
import '../../../models/engagement_models.dart';
class PromotionManagementScreen extends StatelessWidget { const PromotionManagementScreen({super.key}); @override Widget build(BuildContext c){final s=BusinessConfigurationService();return Scaffold(appBar:AppBar(title:const Text('Promotion Management')),floatingActionButton:FloatingActionButton(onPressed:()=>_edit(c,s),child:const Icon(Icons.add)),body:StreamBuilder<List<Promotion>>(stream:s.watchPromotions(),builder:(c,x){final p=x.data??[];return ListView(children:p.map((v)=>ListTile(title:Text(v.code),subtitle:Text('${v.type} • ${v.value} • ${v.status}'),trailing:Switch(value:v.status=='Active',onChanged:(on)=>s.savePromotion(v.id,{'status':on?'Active':'Inactive'}),),onTap:()=>_edit(c,s,v))).toList());}));} Future<void> _edit(BuildContext c,BusinessConfigurationService s,[Promotion? p])async{final code=TextEditingController(text:p?.code??'');final name=TextEditingController(text:p?.id??'');await showDialog(context:c,builder:(d)=>AlertDialog(title:Text(p==null?'Create Promotion':'Edit Promotion'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Name')),TextField(controller:code,decoration:const InputDecoration(labelText:'Promo code'))]),actions:[FilledButton(onPressed:()async{final id=p?.id??code.text.trim().toLowerCase();await s.savePromotion(id,{'name':name.text,'code':code.text.toUpperCase(),'type':p?.type??'percentage','value':p?.value??0,'minimumOrderAmount':p?.minimumOrderAmount??0,'status':'Active'});if(d.mounted)Navigator.pop(d);},child:const Text('Save'))]));}}
